import{_ as e,a as o,o as d,a6 as a}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse(`{"title":"Catalog Category — Detail","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-category-detail","title":"Category Detail (with all translations)","description":"Single category record including the full translations array (all locales present in the DB) and the list of filterable attribute IDs.","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/categories/7\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/json\\"\\n","variables":"id=7\\n","response":"{\\n  \\"id\\": 7,\\n  \\"position\\": 1,\\n  \\"status\\": 1,\\n  \\"parentId\\": 1,\\n  \\"displayMode\\": \\"products_and_description\\",\\n  \\"logoUrl\\": \\"https://example.com/storage/category/7/logo.webp\\",\\n  \\"bannerUrl\\": null,\\n  \\"name\\": \\"Apparel\\",\\n  \\"slug\\": \\"apparel\\",\\n  \\"description\\": \\"Men's and women's apparel\\",\\n  \\"locale\\": \\"en\\",\\n  \\"createdAt\\": \\"2026-01-12T08:15:00+00:00\\",\\n  \\"updatedAt\\": \\"2026-04-30T14:20:09+00:00\\",\\n  \\"translations\\": [\\n    {\\n      \\"locale\\": \\"en\\",\\n      \\"name\\": \\"Apparel\\",\\n      \\"slug\\": \\"apparel\\",\\n      \\"description\\": \\"Men's and women's apparel\\",\\n      \\"metaTitle\\": null,\\n      \\"metaDescription\\": null,\\n      \\"metaKeywords\\": null\\n    },\\n    {\\n      \\"locale\\": \\"fr\\",\\n      \\"name\\": \\"Vêtements\\",\\n      \\"slug\\": \\"vetements\\",\\n      \\"description\\": null,\\n      \\"metaTitle\\": null,\\n      \\"metaDescription\\": null,\\n      \\"metaKeywords\\": null\\n    }\\n  ],\\n  \\"filterableAttributeIds\\": [11, 23]\\n}\\n","commonErrors":[{"error":"Not Found (404)","cause":"The category ID does not exist in the database","solution":"Verify the ID with the listing endpoint \`GET /api/admin/catalog/categories\`"},{"error":"Unauthorized (401)","cause":"Missing, invalid, expired, or revoked admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/categories/categories-detail.md","filePath":"api/rest-api/admin/catalog/categories/categories-detail.md","lastUpdated":1787725411000}`),r={name:"api/rest-api/admin/catalog/categories/categories-detail.md"};function n(i,t,l,s,c,h){return d(),o("div",null,t[0]||(t[0]=[a('<h1 id="catalog-category-—-detail" tabindex="-1">Catalog Category — Detail <a class="header-anchor" href="#catalog-category-—-detail" aria-label="Permalink to &quot;Catalog Category — Detail&quot;">​</a></h1><p>Returns a single category record by ID, including the <strong>full translations array</strong> (every locale present in the database) and the list of <strong>filterable attribute IDs</strong> configured for the category.</p><p>This is the read endpoint to call when an admin needs the complete metadata for a category — e.g. when opening the edit form in the Catalog → Categories UI.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Authentication</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/categories/{id}</code></td><td>GET</td><td>Admin Bearer token</td></tr></tbody></table><p><code>{id}</code> must be a positive integer. Non-numeric values are rejected by a route requirement (<code>\\d+</code>) — this prevents the <code>{id}</code> segment from matching the <code>/tree</code> path of the tree endpoint.</p><h2 id="path-parameter" tabindex="-1">Path Parameter <a class="header-anchor" href="#path-parameter" aria-label="Permalink to &quot;Path Parameter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Yes</td><td>The numeric category ID</td></tr></tbody></table><h2 id="response-shape" tabindex="-1">Response Shape <a class="header-anchor" href="#response-shape" aria-label="Permalink to &quot;Response Shape&quot;">​</a></h2><p>The response is a single JSON object (not wrapped in <code>{ data }</code>) with the following fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Category ID</td></tr><tr><td><code>position</code></td><td>integer</td><td>Display order position</td></tr><tr><td><code>status</code></td><td>integer</td><td><code>1</code> = enabled, <code>0</code> = disabled</td></tr><tr><td><code>parentId</code></td><td>integer|null</td><td>Parent category ID; <code>null</code> for root nodes</td></tr><tr><td><code>displayMode</code></td><td>string|null</td><td>Category display mode (e.g. <code>products_and_description</code>)</td></tr><tr><td><code>logoUrl</code></td><td>string|null</td><td>Storage URL for the category logo; <code>null</code> if not set</td></tr><tr><td><code>bannerUrl</code></td><td>string|null</td><td>Storage URL for the category banner; <code>null</code> if not set</td></tr><tr><td><code>name</code></td><td>string|null</td><td>Category name in the current app locale</td></tr><tr><td><code>slug</code></td><td>string|null</td><td>URL slug in the current app locale</td></tr><tr><td><code>description</code></td><td>string|null</td><td>Category description in the current app locale</td></tr><tr><td><code>locale</code></td><td>string|null</td><td>App locale used for the top-level <code>name</code>/<code>slug</code>/<code>description</code> fields</td></tr><tr><td><code>createdAt</code></td><td>string|null</td><td>ISO 8601 creation timestamp</td></tr><tr><td><code>updatedAt</code></td><td>string|null</td><td>ISO 8601 last-update timestamp</td></tr><tr><td><code>translations</code></td><td>array</td><td>All locale translations (see below)</td></tr><tr><td><code>filterableAttributeIds</code></td><td>array|null</td><td>Integer IDs of attributes configured as filterable for this category</td></tr></tbody></table><h3 id="translations-item-shape" tabindex="-1"><code>translations[]</code> item shape <a class="header-anchor" href="#translations-item-shape" aria-label="Permalink to &quot;`translations[]` item shape&quot;">​</a></h3><p>Each entry in the <code>translations</code> array corresponds to one locale row in <code>category_translations</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>locale</code></td><td>string</td><td>Locale code (e.g. <code>en</code>, <code>fr</code>)</td></tr><tr><td><code>name</code></td><td>string|null</td><td>Category name in this locale</td></tr><tr><td><code>slug</code></td><td>string|null</td><td>URL slug in this locale</td></tr><tr><td><code>description</code></td><td>string|null</td><td>Description in this locale</td></tr><tr><td><code>metaTitle</code></td><td>string|null</td><td>SEO meta title in this locale</td></tr><tr><td><code>metaDescription</code></td><td>string|null</td><td>SEO meta description in this locale</td></tr><tr><td><code>metaKeywords</code></td><td>string|null</td><td>SEO meta keywords in this locale</td></tr></tbody></table><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP</th><th>Detail</th></tr></thead><tbody><tr><td><code>401</code></td><td><code>Unauthenticated.</code></td></tr><tr><td><code>404</code></td><td><code>{&quot;type&quot;: &quot;/errors/404&quot;, &quot;title&quot;: &quot;Not Found&quot;, &quot;status&quot;: 404, &quot;detail&quot;: &quot;Category not found.&quot;}</code></td></tr></tbody></table><p>A non-numeric <code>{id}</code> also returns <code>404</code>. The route constrains the segment to digits, which is what keeps <code>/catalog/categories/tree</code> routing to the tree endpoint instead of being read as an id.</p><h2 id="working-with-this-endpoint" tabindex="-1">Working With This Endpoint <a class="header-anchor" href="#working-with-this-endpoint" aria-label="Permalink to &quot;Working With This Endpoint&quot;">​</a></h2><ul><li><strong><code>translations</code> carries one entry per stored locale row</strong>, not just the requested one, so a multi-locale store returns them all. Unset text fields come back as the empty string <code>&quot;&quot;</code>, not <code>null</code>.</li><li><strong>The top-level <code>name</code>, <code>slug</code>, and <code>description</code> duplicate the requested locale&#39;s entry.</strong> They are a shortcut, not extra data — <code>locale</code> tells you which entry they came from.</li><li><strong><code>filterableAttributeIds</code> is a flat integer array.</strong> <code>[]</code> means none are configured; it is the layered-navigation attribute set for this category, not the products&#39; attributes.</li><li><strong>The response is a bare object</strong>, unlike the listing, which wraps rows in <code>{ data, meta }</code>.</li></ul>',19)]))}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
